//! NumPy's `default_rng(seed).integers(low, high, dtype=int64)`, bit for bit:
//! `SeedSequence` entropy mixing, the `PCG64` (XSL-RR 128/64) bit generator, and the
//! Lemire bounded-integer draw NumPy uses for 64-bit ranges.
//!
//! Exists for one reason: the checkpoint's engram hash multipliers are drawn this way
//! (`inference/engram.py::compute_hash_multipliers`), and a multiplier that differs by
//! one bit rehashes the whole 768M-row table. Verified against NumPy 2.5.4 output in
//! `rust/fixtures/engram_truth.json` (generated by `rust/tools/engram_truth.py`).

const INIT_A: u32 = 0x43b0_d7e5;
const MULT_A: u32 = 0x931e_8875;
const INIT_B: u32 = 0x8b51_f9dd;
const MULT_B: u32 = 0x58f3_8ded;
const MIX_MULT_L: u32 = 0xca01_f9dd;
const MIX_MULT_R: u32 = 0x4973_f715;
const XSHIFT: u32 = 16;
const POOL_SIZE: usize = 4;

const PCG_MULT: u128 = (0x2360_ED05_1FC6_5DA4u128 << 64) | 0x4385_DF64_9FCC_F645u128;

fn hashmix(value: u32, hash_const: &mut u32) -> u32 {
    let mut v = value ^ *hash_const;
    *hash_const = hash_const.wrapping_mul(MULT_A);
    v = v.wrapping_mul(*hash_const);
    v ^ (v >> XSHIFT)
}

fn mix(x: u32, y: u32) -> u32 {
    let r = MIX_MULT_L.wrapping_mul(x).wrapping_sub(MIX_MULT_R.wrapping_mul(y));
    r ^ (r >> XSHIFT)
}

/// `numpy.random.SeedSequence(entropy)` for a non-negative integer entropy, no spawn key.
pub struct SeedSequence {
    pool: [u32; POOL_SIZE],
}

impl SeedSequence {
    pub fn new(entropy: u128) -> Self {
        // _int_to_uint32_array: little-endian 32-bit words, [0] for zero
        let mut words = Vec::new();
        let mut n = entropy;
        if n == 0 {
            words.push(0u32);
        }
        while n > 0 {
            words.push((n & 0xffff_ffff) as u32);
            n >>= 32;
        }
        let mut pool = [0u32; POOL_SIZE];
        let mut hash_const = INIT_A;
        for (i, slot) in pool.iter_mut().enumerate() {
            let w = words.get(i).copied().unwrap_or(0);
            *slot = hashmix(w, &mut hash_const);
        }
        for i_src in 0..POOL_SIZE {
            for i_dst in 0..POOL_SIZE {
                if i_src != i_dst {
                    let h = hashmix(pool[i_src], &mut hash_const);
                    pool[i_dst] = mix(pool[i_dst], h);
                }
            }
        }
        for &w in words.iter().skip(POOL_SIZE) {
            for slot in pool.iter_mut() {
                let h = hashmix(w, &mut hash_const);
                *slot = mix(*slot, h);
            }
        }
        SeedSequence { pool }
    }

    /// `generate_state(n_words, np.uint64)`: 32-bit words drawn round-robin from the
    /// pool, then viewed little-endian as u64.
    pub fn generate_state_u64(&self, n_words: usize) -> Vec<u64> {
        let mut hash_const = INIT_B;
        let mut out32 = Vec::with_capacity(n_words * 2);
        for i in 0..n_words * 2 {
            let mut v = self.pool[i % POOL_SIZE] ^ hash_const;
            hash_const = hash_const.wrapping_mul(MULT_B);
            v = v.wrapping_mul(hash_const);
            v ^= v >> XSHIFT;
            out32.push(v);
        }
        out32.chunks_exact(2).map(|w| (w[0] as u64) | ((w[1] as u64) << 32)).collect()
    }
}

/// NumPy's `PCG64` bit generator (pcg_setseq_128_xsl_rr_64).
pub struct Pcg64 {
    state: u128,
    inc: u128,
}

impl Pcg64 {
    /// `np.random.default_rng(seed)`.
    pub fn from_seed(seed: u128) -> Self {
        let v = SeedSequence::new(seed).generate_state_u64(4);
        let initstate = ((v[0] as u128) << 64) | v[1] as u128;
        let initseq = ((v[2] as u128) << 64) | v[3] as u128;
        let mut rng = Pcg64 { state: 0, inc: (initseq << 1) | 1 };
        rng.step();
        rng.state = rng.state.wrapping_add(initstate);
        rng.step();
        rng
    }

    fn step(&mut self) {
        self.state = self.state.wrapping_mul(PCG_MULT).wrapping_add(self.inc);
    }

    pub fn next_u64(&mut self) -> u64 {
        self.step();
        let s = self.state;
        let x = ((s >> 64) as u64) ^ (s as u64);
        x.rotate_right((s >> 122) as u32)
    }

    /// `bounded_lemire_uint64`: uniform in `[0, rng]` inclusive, `rng < u64::MAX`.
    fn bounded_lemire_u64(&mut self, rng: u64) -> u64 {
        let rng_excl = rng + 1;
        let mut m = (self.next_u64() as u128) * rng_excl as u128;
        let mut leftover = m as u64;
        if leftover < rng_excl {
            let threshold = (u64::MAX - rng) % rng_excl;
            while leftover < threshold {
                m = (self.next_u64() as u128) * rng_excl as u128;
                leftover = m as u64;
            }
        }
        (m >> 64) as u64
    }

    /// `Generator.integers(low, high, size=n, dtype=np.int64)` for a range wider than
    /// 32 bits (the only case the engram multipliers hit). Narrower ranges take NumPy's
    /// buffered 32-bit path, which is not ported; they are refused rather than guessed.
    pub fn integers_i64(&mut self, low: i64, high: i64, n: usize) -> Vec<i64> {
        assert!(high > low, "empty range");
        let rng = (high - 1 - low) as u64;
        assert!(
            rng > 0xffff_ffff && rng != u64::MAX,
            "only the 64-bit Lemire path is ported (range {rng})"
        );
        (0..n).map(|_| low.wrapping_add(self.bounded_lemire_u64(rng) as i64)).collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn truth() -> serde_json::Value {
        let raw = include_str!("../../../fixtures/engram_truth.json");
        serde_json::from_str(raw).unwrap()
    }

    #[test]
    fn matches_numpy_default_rng_integers() {
        let t = truth();
        for (seed, values) in t["rng_check"].as_object().unwrap() {
            let seed: u128 = seed.parse().unwrap();
            let want: Vec<i64> =
                values.as_array().unwrap().iter().map(|v| v.as_i64().unwrap()).collect();
            let got = Pcg64::from_seed(seed).integers_i64(0, 46_545_386_853_491, want.len());
            assert_eq!(got, want, "seed {seed}");
        }
    }
}
